"""Retry rejected contact-station boundaries with independent corner weights.

Keep the original boundary construction whenever its complete check passes.
A rejected boundary may try the same station heuristic per corner, followed
by the unchanged complete polygon check. This avoids moving an already exact
arc because a different side required a smaller blend. It is an opt-in retry,
not a general error or edit-continuity certificate.
"""
import bpy

from . import curved_mesh_boundary_nodes as bounds
from .curved_quad_fair_nodes import assign_group

c = bounds.c


def graph(tree):
    g = c.Graph.__new__(c.Graph); g.g = tree; g.count = len(tree.nodes); g.frame = None
    return g


def side_errors(original):
    name = original.name+' / Per-corner errors v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    result = original.copy(); result.name = name; g = graph(result)
    begin, = [n for n in result.nodes if n.bl_idname == 'GeometryNodeRepeatInput']
    g.socket('Side Errors', 'NodeSocketGeometry', 'OUTPUT')
    out, = [n for n in result.nodes if n.type == 'GROUP_OUTPUT' and n.is_active_output]
    g.bind(begin.paired_output.outputs['Geometry'], out.inputs['Side Errors'])
    return result


def weighted_stations(original):
    name = original.name+' / Independent corner weights v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    result = original.copy(); result.name = name; g = graph(result)
    g.socket('Corner Weights', 'NodeSocketGeometry')
    inp, = [n for n in result.nodes if n.type == 'GROUP_INPUT']
    targets = [n for n in result.nodes if n.type == 'GROUP' and 'Blend' in n.inputs
               and n.inputs['Blend'].is_linked
               and n.inputs['Blend'].links[0].from_node == inp
               and n.inputs['Blend'].links[0].from_socket.name in ('Blend', 'Contact Blend')]
    assert len(targets) in (1, 2), ('Expected the checked/layout station callers', len(targets))
    for node in targets:
        owner = node.inputs['Index'].links[0].from_socket
        g.bind(c._read(g, inp.outputs['Corner Weights'], '_cw_weight', owner), node.inputs['Blend'])
    return result


def retry(original):
    result = original.copy(); result.name = 'Per-corner contact retry / '+original.name; g = graph(result)
    check, = [n for n in result.nodes if n.type == 'GROUP'
              and n.label == 'Unchanged complete 50 micrometre polygon bound']
    raw, = [n for n in result.nodes if n.type == 'GROUP'
            and n.label == 'Same direct quad construction with mesh-only knots']
    proposal, = [n for n in result.nodes if n.type == 'GROUP'
                 and n.label.startswith('Measure the complete unblended proposal')]
    # Capture only the existing publication consumers before introducing the
    # new admission dependency, so rerouting cannot make a feedback cycle.
    consumers = {n.name: {s.name: [link.to_socket for link in s.links] for s in n.outputs}
                 for n in (check, raw)}
    assign_group(proposal, side_errors(proposal.node_tree))
    error = c.named(g, '_mb_difference')
    weight = g.math('MINIMUM', 1., g.math('DIVIDE', .25*bounds.LOCAL_BOUND,
                                         g.math('MAXIMUM', error, 1e-12)))
    weight = weight*weight
    weights = c._store(g, proposal.outputs['Side Errors'], '_cw_weight', weight)
    # Missing/invalid records cannot qualify the retry; the original path and
    # every original input and complete polygon check are still present.
    inp, = [n for n in result.nodes if n.type == 'GROUP_INPUT']
    table_valid = g.math('COMPARE', c._count(g, weights), c._count(g, inp.outputs['Mouths']))
    table_valid *= c._stat(g, weights, c.named(g, '_mb_valid', 'BOOLEAN'))
    need = 1.-c.V(g, check.outputs['Valid'])
    replacements = []
    for source, label in ((raw, 'Retry direct layout with independent corner weights'),
                          (check, 'Retry unchanged boundary check per corner')):
        node = g.node('GeometryNodeGroup', label); node.node_tree = weighted_stations(source.node_tree)
        for socket in source.inputs:
            if socket.is_linked: g.bind(socket.links[0].from_socket, node.inputs[socket.name])
            elif hasattr(socket, 'default_value'): node.inputs[socket.name].default_value = socket.default_value
        g.bind(weights, node.inputs['Corner Weights'])
        replacements.append((source, node))
    kinds = {'NodeSocketGeometry': 'GEOMETRY', 'NodeSocketBool': 'BOOLEAN',
             'NodeSocketFloat': 'FLOAT', 'NodeSocketInt': 'INT', 'NodeSocketVector': 'VECTOR'}
    for source, alternate in replacements:
        for socket in source.outputs:
            if not consumers[source.name][socket.name]: continue
            value = alternate.outputs[socket.name]
            if socket.bl_idname == 'NodeSocketBool': value = c.V(g, value)*table_valid
            value = c.choose(g, need, value, socket, kinds[socket.bl_idname])
            for target in consumers[source.name][socket.name]: g.bind(value, target)
    g.socket('Corner Weights', 'NodeSocketGeometry', 'OUTPUT')
    out, = [n for n in result.nodes if n.type == 'GROUP_OUTPUT' and n.is_active_output]
    g.bind(weights, out.inputs['Corner Weights'])
    result['st_contact_corner_weight_policy'] = 'retry_rejected_boundary_per_corner_v1'
    return result


def identity_retry(original):
    """Try original stations only after the existing checked source rejects.

    The original analytic stations are a construction candidate, not an escape
    from the boundary test. The copied source retains every chart, count,
    complete-curb and seam check. The enclosing pattern still checks cells,
    footprint and profiles before publishing pavement.
    """
    if original.get('st_contact_corner_weight_policy') != 'retry_rejected_boundary_per_corner_v1':
        raise ValueError('Identity retry requires the checked independent-corner station source')
    name = 'Prochitecture Streets / Checked original contact station fallback / '+str(original.name)
    # Blender's name limit is smaller than some saved diagnostic source names.
    import hashlib
    name = 'Prochitecture Streets / Checked original contact station fallback v1 / '+hashlib.sha256(name.encode()).hexdigest()[:16]
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    memo = {}; changed = []

    def copy(tree):
        if tree.as_pointer() in memo: return memo[tree.as_pointer()]
        children = [(n.name, copy(n.node_tree)) for n in tree.nodes if n.type == 'GROUP' and n.node_tree]
        updates = [(key, child) for key, child in children if child != tree.nodes[key].node_tree]
        targets = [n.name for n in tree.nodes if n.type == 'GROUP' and n.node_tree
                   and n.node_tree.name.startswith('Prochitecture Streets / Reserved lead contact stations v5')
                   and 'Blend' in n.inputs]
        result = tree.copy() if updates or targets else tree
        for key, child in updates: assign_group(result.nodes[key], child)
        for key in targets:
            socket = result.nodes[key].inputs['Blend']
            for link in list(socket.links): result.links.remove(link)
            socket.default_value = 0.; changed.append((tree.name, key))
        memo[tree.as_pointer()] = result; return result

    reference = copy(original)
    if not changed: raise ValueError('No bounded station calls found for the identity candidate')
    g = c.Graph(name)
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    for s in sockets: g.socket(s.name, s.socket_type, s.in_out, default=getattr(s, 'default_value', None))
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    calls = []
    for label, tree in (('Existing checked contact stations', original),
                        ('Original stations with unchanged complete boundary checks', reference)):
        call = g.node('GeometryNodeGroup', label); call.node_tree = tree
        for socket in sockets:
            if socket.in_out == 'INPUT': g.bind(inp.outputs[socket.name], call.inputs[socket.name])
        calls.append(call)
    first, second = calls
    valid = c.V(g, first.outputs['Inputs Valid'])*c.V(g, first.outputs['Seams Valid'])
    alternate = c.V(g, second.outputs['Inputs Valid'])*c.V(g, second.outputs['Seams Valid'])
    use = c.choose(g, valid, False, alternate, 'BOOLEAN')
    kinds = {'NodeSocketGeometry':'GEOMETRY', 'NodeSocketBool':'BOOLEAN',
             'NodeSocketFloat':'FLOAT', 'NodeSocketInt':'INT', 'NodeSocketVector':'VECTOR'}
    for socket in sockets:
        if socket.in_out != 'OUTPUT': continue
        value = second.outputs[socket.name]
        if socket.socket_type == 'NodeSocketGeometry':
            # Keep diagnostic weights consistent with the actual identity
            # construction, rather than the rejected heuristic's old weights.
            key = '_cw_weight' if socket.name == 'Corner Weights' else 'st_cq_contact_blend'
            value = c._store(g, value, key, 0.)
        value = c.choose(g, use, value, first.outputs[socket.name], kinds[socket.socket_type])
        g.bind(value, out.inputs[socket.name])
    if original.get('st_initial_samples_only'): g.g['st_initial_samples_only'] = 1
    g.g['st_contact_identity_fallback'] = 1
    g.g['st_contact_identity_station_calls'] = len(changed)
    return g.g


def replace_saved(root, *, identity_fallback=False):
    memo = {}; changes = []
    def visit(tree):
        if tree in memo: return memo[tree]
        if tree.get('st_contact_identity_fallback'):
            raise ValueError('Original station fallback already installed')
        if any(n.type == 'GROUP' and n.label == 'Unchanged complete 50 micrometre polygon bound'
               for n in tree.nodes):
            if tree.get('st_contact_corner_weight_policy') and not identity_fallback:
                raise ValueError('Independent corner retry already installed')
            result = tree if tree.get('st_contact_corner_weight_policy') else retry(tree)
            if identity_fallback: result = identity_retry(result)
            changes.append(tree.name)
        else:
            children = [(n.name, visit(n.node_tree)) for n in tree.nodes if n.type == 'GROUP' and n.node_tree]
            changed = [(name, child) for name, child in children if child != tree.nodes[name].node_tree]
            result = tree.copy() if changed else tree
            for name, child in changed: assign_group(result.nodes[name], child)
        memo[tree] = result
        return result
    result = visit(root)
    if not changes: raise ValueError('No checked contact-station wrappers found')
    return result, sorted(set(changes))
